begin;
select plan(12);
select has_function('public','reset_game_for_testing',array['text','uuid'],'test reset RPC exists');
select is((select reset_enabled from public.games where code='TEST01'),true,'TEST01 reset enabled');
insert into auth.users(id,aud,role,email,is_anonymous) values ('00000000-0000-0000-0000-000000000901','authenticated','authenticated','reset-staff@example.test',false), ('00000000-0000-0000-0000-000000000903','authenticated','authenticated','reset-player@example.test',true);
insert into public.staff_members(id,auth_user_id,display_name,active) values ('40000000-0000-0000-0000-000000000901','00000000-0000-0000-0000-000000000901','Reset Staff',true);
insert into public.players(id,game_id,auth_user_id,table_id,seat_number,nickname) values ('20000000-0000-0000-0000-000000000901','a0000000-0000-0000-0000-000000000050','00000000-0000-0000-0000-000000000903','b0000000-0000-0000-0000-000000000051',1,'Reset Player');
insert into public.game_role_assignments(player_id,game_id,role) values ('20000000-0000-0000-0000-000000000901','a0000000-0000-0000-0000-000000000050','liar');
insert into public.game_role_acknowledgements(player_id,game_id) values ('20000000-0000-0000-0000-000000000901','a0000000-0000-0000-0000-000000000050');
update public.games set lifecycle='live', narrative_phase='pressure' where code='TEST01';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000901',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000901","role":"authenticated","is_anonymous":false}',true);
select is((select lifecycle from public.reset_game_for_testing('TEST01','90000000-0000-0000-0000-000000000903')),'checkin_open','reset succeeds');
reset role;
select is((select narrative_phase from public.games where code='TEST01'),'lobby','reset returns lobby');
select is((select count(*) from public.players where game_id='a0000000-0000-0000-0000-000000000050'),0::bigint,'players are expelled');
select is((select count(*) from auth.users where id='00000000-0000-0000-0000-000000000903'),1::bigint,'auth user preserved');
select is((select count(*) from public.game_role_assignments where game_id='a0000000-0000-0000-0000-000000000050'),0::bigint,'roles cleared');
select is((select count(*) from public.game_role_acknowledgements where game_id='a0000000-0000-0000-0000-000000000050'),0::bigint,'acknowledgements cleared');
select is((select scenario_version_id from public.games where code='TEST01'),'e0000000-0000-0000-0000-000000000015'::uuid,'scenario preserved');
select is((select count(*) from public.game_tables where game_id='a0000000-0000-0000-0000-000000000050'),5::bigint,'tables preserved');
set local role authenticated;
select is((select count(*) from public.reset_game_for_testing('TEST01','90000000-0000-0000-0000-000000000903')),1::bigint,'retry idempotent');
reset role;
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('table_coin_ledger','game_auctions','game_auction_bids','game_auction_commands')),'removed runtime tables absent');
select * from finish();
rollback;
